import{createLogger}from"#internal/logging.js";import{setTimeout}from"node:timers/promises";import{classifyModelCallError}from"#harness/model-call/errors.js";import{decide}from"#shared/restriction.js";const log=createLogger(`harness.tool-loop`),ALLOW_RETRY={delayMs:0,retry:!0},STOP_RETRY={retry:!1},retryLaw={meet:(e,t)=>e.retry?t.retry?{delayMs:Math.max(e.delayMs,t.delayMs),retry:!0}:t:e,open:ALLOW_RETRY},BUILT_IN=[({error:e})=>classifyModelCallError(e)===`retry`?ALLOW_RETRY:STOP_RETRY,({attempt:e})=>e<3?ALLOW_RETRY:STOP_RETRY,({attempt:e})=>({delayMs:500*2**(e-1)+Math.floor(Math.random()*250),retry:!0})];async function runModelCallWithRetries(e,t,n){let r=[...BUILT_IN,...t.policies??[]];for(let i=1;;i++){n?.throwIfAborted();try{return await e()}catch(e){n?.throwIfAborted();let a=decide(retryLaw,r,{attempt:i,error:e});if(!a.retry)throw e;let{delayMs:o}=a;log.warn(`model call failed transiently — retrying`,{attempt:i,delayMs:o,sessionId:t.sessionId,turnId:t.turnId,error:e}),await t.onRetry?.(e),await setTimeout(o,void 0,{signal:n})}}}export{ALLOW_RETRY,STOP_RETRY,runModelCallWithRetries};